+                        testCase.earlySchema = earlySchema.toString();
+                        earlySchema.setLength(0);
+                        query.setLength(0);
+                    }
+                    // keep reading the query
+                    else {
+                        query.append(line);
+                        query.append("\r\n");
+                    }
+                }
+            }
